from abc import abstractmethod, ABCMeta
import time
import logging
from six import add_metaclass
from ta_attenuator.fading_scenario import wrap_into_fading_scenario


@add_metaclass(ABCMeta)
class Attenuator(object):
    """
    Attenuator API abstract base class. Parent class for implementation.
    """

    def __init__(self):
        """
        Basic constructor.
        """
        super(Attenuator, self).__init__()
        self.used_ports = []

    def __enter__(self):
        self.connect_attenuator_controller()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.disconnect_attenuator_controller()

    @abstractmethod
    def connect_attenuator_controller(self, **kwargs):
        """
        Derived should put here code required to establish connection with attenuation controller
        allowing to change attenuation on specific RF-path of that device
        """
        pass

    @abstractmethod
    def disconnect_attenuator_controller(self, **kwargs):
        """
        Derived should put here code required to release connection with attenuation controller
        """
        pass

    def reserve_port(self, port_id):
        """Reserve port on attenuator and raise exception if it was already used"""
        if port_id in self.used_ports:
            raise RfPathAlreadyUsed('Port ID {} was already used! Already used ports = {}'.format(port_id, str(self.used_ports)))
        self.used_ports.append(port_id)
        logging.debug('Reserved ports = {}'.format(str(self.used_ports)))

    def release_port(self, port_id):
        """Release port on attenuator"""
        if port_id in self.used_ports:
            logging.debug('Releasing port = {}'.format(str(port_id)))
            self.used_ports.remove(port_id)
            logging.debug('Reserved ports = {}'.format(str(self.used_ports)))
        else:
            raise ReleasingNotReservedPort("Trying to release port {}, which was not reserved".format(port_id))

    def check_if_port_is_reserved(self, port_id):
        """Check if given port is reserved"""
        if port_id in self.used_ports:
            return True
        return False

    def set_single_rf_path_attenuation(self, rf_path_address, attenuation_value, confirm=True):
        """
        Set attenuation for single RF-path inside attenuator device.

        It is the basic building block for other functionalities of Attenuator class, means
        it works as fallback function - if given attenuator doesn't support setting attenuation
        for multiple RF-paths via single command then we can just loop over this method.

        Value expressed in % (like '10%') means 10% of (max attenuation - min attenuation).
        '0%' means min attenuation; 100% is max attenuation.

        :param rf_path_address: identification of rf-path specific for given attenuator HW, f.ex. pins number
        :param attenuation_value: value to set in dB or %. It is string like '20dB' or '10%'
        :param confirm: if True then read attenuation from attenuator to confirm that it was correctly set
        :return: None
        """
        attenuation_value = self.convert_and_check_attenuation_value(attenuation_value)
        self._set_single_rf_path_decibel_attenuation(rf_path_address, attenuation_value, confirm)

    def convert_and_check_attenuation_value(self, attenuation_value):
        """
        Convert attenuation value delivered by user to format usable by ta_attenuator library.
        :param attenuation_value: value to set in dB or %. It is string like '20dB' or '10%'
        :return: attenuation value converted to value usable by ta_attenuator library e.g. 5 db
        """
        real_att_value = self._convert_attenuation_value_to_db(attenuation_value)
        max_value = self.get_max_decibel_attenuation()
        min_value = self.get_min_decibel_attenuation()
        if real_att_value > max_value or real_att_value < min_value:
            raise AttenuationOutOfBoundsException(attenuation_value, real_att_value,
                                                  min_value,
                                                  max_value)
        return real_att_value

    def _convert_attenuation_value_to_db(self, attenuation_value):
        try:
            if '%' in attenuation_value:
                num = self._extract_numeric_value(attenuation_value)
                return self.get_min_decibel_attenuation() + \
                    0.01 * num * (self.get_max_decibel_attenuation() - self.get_min_decibel_attenuation())
            elif 'db' in attenuation_value or 'dB' in attenuation_value:
                return self._extract_numeric_value(attenuation_value)
            else:
                raise ValueError("Attenuation value {} passed in not suitable format.\n".format(attenuation_value) +
                                 "Unit (% or db) was not specified.")
        except TypeError:
            raise TypeError("Attenuation passed in not suitable format {}, while an iterable (string, unicode)"
                            " was expected".format(type(attenuation_value)))

    def _extract_numeric_value(self, attenuation_value):
        num = attenuation_value.replace('db', '').replace('dB', '').replace('%', '')
        num = float(num)
        return num

    @abstractmethod
    def _set_single_rf_path_decibel_attenuation(self, rf_path_address, attenuation_value_db, confirm=True):
        """
        Set attenuation for single RF-path inside attenuator device.
        It should be implemented by specific attenuator impl.
        :param rf_path_address: identification of rf-path specific for given attenuator HW, f.ex. pins number
        :param attenuation_value_db: float or int in db
        """
        pass

    @abstractmethod
    def get_max_decibel_attenuation(self):
        """
        Returns Maximal value of attenuation possible on this attenuator. For ex. 95 dB
        :return: float
        """
        return 100.0  # just to make pycharm not highlighting invoke of this method

    @abstractmethod
    def get_min_decibel_attenuation(self):
        """
        Returns Minimal value of attenuation possible on this attenuator. For ex. 5 dB
        :return: float
        """
        return 0  # just to make pycharm not highlighting invoke of this method

    def set_single_rf_path_max_attenuation(self, rf_path_address):
        """
        Set attenuation of given RF-path to maximum value supported by given attenuator device.
        """
        self.set_single_rf_path_attenuation(rf_path_address=rf_path_address, attenuation_value="100%")

    def set_single_rf_path_min_attenuation(self, rf_path_address):
        """
        Set attenuation of given RF-path to minimum value supported by given attenuator device.
        """
        self.set_single_rf_path_attenuation(rf_path_address=rf_path_address, attenuation_value="0%")

    def set_rf_paths_attenuation(self, rf_paths_addresses, attenuation_value, confirm=True):
        """
        Set attenuation for multiple RF-paths inside attenuator device.

        NOTE: we intentionally do not provide set_all_rf_paths_attenuation API.
        The decision comes from experience: very often single attenuator device is shared between multiple teams.
        One person/team is using subset of all RF-paths controlled by device; others use the rest.
        We don't want situation where person/team unintentionally impacts device usage of 'not owned RF-paths'.
        So, as a user please do take care of using 'RF-paths' connecting your RF-equipment.

        :param rf_paths_addresses: list of rf_path_address
        :param attenuation_value: value to set in dB or %. It is string like '20dB' or '10%'
        :return: None
        """
        # default implementation - if given attenuation device has no attenuate-multiple-RF-paths command
        for rf_path_address in rf_paths_addresses:
            self.set_single_rf_path_attenuation(rf_path_address=rf_path_address, attenuation_value=attenuation_value, confirm=confirm)

    def set_rf_paths_max_attenuation(self, rf_paths_addresses):
        """
        Set attenuation of multiple RF-paths to maximum value supported by given attenuator device.
        """
        self.set_rf_paths_attenuation(rf_paths_addresses=rf_paths_addresses, attenuation_value="100%")

    def set_rf_paths_min_attenuation(self, rf_paths_addresses):
        """
        Set attenuation of multiple RF-paths to minimum value supported by given attenuator device.
        """
        self.set_rf_paths_attenuation(rf_paths_addresses=rf_paths_addresses, attenuation_value="0%")

    def execute_fading_scenario(self, scenario, confirm=True):
        """
        Execute fading via attenuator. Fading scenario is generic - defined by scenario scenario_iterator.

        :param scenario: may be either fading_scenario.FadingScenario class instance or
        scenario_iterator object yielding description of fading-single-step

        fading-single-step has a form of dictionary, see example::

            {'synchronous_attenuations': {'rf_path_1_address': '0%',
                                          'rf_path_2_address': '100%'},
             'next_step_delay': 0.5}  # in seconds

        Here is scenario_iterator equally attenuating 2 RF-paths from min to max over given time period::

            def close_rf_path_pair(rf_path_1_address, rf_path_2_address, closing_duration):
                if closing_duration <= 1:
                    steps_number = 5
                else:
                    steps_number = 10
                steps_delay = closing_duration / steps_number
                if steps_delay < 0.2:
                    steps_delay = 0.2
                attenuation_step = 100 / steps_number
                closing_time = 0
                current_attenuation = 0
                while closing_time < closing_duration:
                    current_attenuation_str = '{}%'.format(current_attenuation)
                    fading_step = {'synchronous_attenuations': {'rf_path_1_address': current_attenuation_str,
                                                                'rf_path_2_address': current_attenuation_str},
                                   'next_step_delay': steps_delay}
                    yield fading_step
                    current_attenuation = current_attenuation + attenuation_step

        :return: None
        """
        # simplest execution - synchronous one:
        # * doesn't set all rf-paths of fading_step 'at same time'
        # * uses time.sleep() - not good for Twisted/asyncio parallelism
        # * whole this 'fading process' might be implemented as Future (so might go to background till completed)
        #   * see ta_command for Future with exchangeable 'parallelism machinery'
        fading_scenario = wrap_into_fading_scenario(scenario)

        with fading_scenario:
            while not fading_scenario.is_finished():
                self._set_rf_paths_to_given_attenuations(fading_scenario, confirm)
                delay_to_nearest_attenuation_timepoint = fading_scenario.get_nearest_attenuation_timepoint() - time.time()
                if delay_to_nearest_attenuation_timepoint > 0:
                    time.sleep(delay_to_nearest_attenuation_timepoint)

    def _set_rf_paths_to_given_attenuations(self, fading_scenario, confirm=True):
        for rf_path in fading_scenario.get_rf_paths():
            rf_value = fading_scenario.get_attenuation_on_rf_path(rf_path)
            self.set_single_rf_path_attenuation(rf_path_address=rf_path,
                                                attenuation_value=rf_value,
                                                confirm=confirm)


class CellAttenuation(object):
    """
    Utility class to treat all RF-paths of single cell as single entity from attenuation view point.

    Cell may be of different antennas number (SISO, SIMO, MIMO) so, cell may have multiple RF-paths.
    """

    def __init__(self, attenuator, rf_paths_of_cell):
        """
        Define cell attenuation by specifying which RF-paths of provided attenuator belong to given cell

        :param attenuator: device that does real attenuation
        :param rf_paths_addresses: RF-paths addresses of attenuator belonging to given cell
        """
        super(CellAttenuation, self).__init__()
        self.rf_paths_of_cell = rf_paths_of_cell
        self.attenuator = attenuator

    def set_attenuation(self, attenuation_value, confirm=True):
        """
        Set cell attenuation.

        :param attenuation_value: value to set in dB or %. It is string like '20dB' or '10%'
        :return: None
        """
        self.attenuator.set_rf_paths_attenuation(rf_paths_addresses=self.rf_paths_of_cell,
                                                 attenuation_value=attenuation_value,
                                                 confirm=confirm)

    def set_max_attenuation(self):
        """
        Set cell attenuation to maximum value supported by given attenuator device.
        """
        self.attenuator.set_rf_paths_max_attenuation(rf_paths_addresses=self.rf_paths_of_cell)

    def set_min_attenuation(self):
        """
        Set cell attenuation to minimum value supported by given attenuator device.
        """
        self.attenuator.set_rf_paths_min_attenuation(rf_paths_addresses=self.rf_paths_of_cell)

        # TODO: how to use cell for fading?


class RfPathAlreadyUsed(Exception):
    """Exception which should be raised when rf paths are already used"""
    pass


class AttenuationOutOfBoundsException(Exception):
    """Exception which should be raised when attenuation is out of range."""
    def __init__(self, src_att_string, att_val, min_val, max_val):
        self.src_att_string = src_att_string
        self.att_val = att_val
        self.min_val = min_val
        self.max_val = max_val
        msgp = "Given value {} dB is out of range [{} dB, {} dB]. Given value string: {}"
        msg = msgp.format(att_val, min_val, max_val, src_att_string)
        super(AttenuationOutOfBoundsException, self).__init__(msg)


class ReleasingNotReservedPort(Exception):
    """Exception class"""
    pass


class ChangingAttenutionValueOfNotReservedPort(Exception):
    """Exception class"""
    pass


class ReadingAttenuationValueOfNonexistentRFPath(Exception):
    """Exception class"""
    pass


class AttenuationValueIsOtherThanExpected(Exception):
    """Exception class"""
    pass
